package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_24_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Test case for a number with a decimal point followed by 'L'
        String testNumber = "123.45L";
        // The buggy version incorrectly returns true
        assertFalse("The number '123.45L' should not be considered valid.", NumberUtils.isNumber(testNumber));
    }
}

